SELECT 
FROM pos_shift s


    s.store_id = #{q.storeId}
    AND s.terminal_id = #{q.terminalId}
    AND s.cashier_id = #{q.cashierId}
    AND s.status = #{q.status}
    AND s.business_date >= #{q.begin}
    AND s.business_date <= #{q.end}

ORDER BY s.id DESC

SELECT 
FROM pos_shift s

WHERE s.id = #{id}

SELECT COUNT(*) FROM pos_payment
WHERE shift_id = #{shiftId}
  AND ((status = 'SUCCESS' AND sale_id IS NULL AND topup_id IS NULL AND amount > 0) OR (amount < 0 AND status = 'PENDING'))
